enum PriorityScore {
  HIGH
  LOW
}

class HospitalHouseMD {}

class Patient {
  + signConsent()
  + retractConsent()
}

class Doctor {
  + approveDiagnosis()
  + downgradeTreatment()
}

class Nurse {}

class Illness {
  + priorityScore : PriorityScore
}

class Diagnosis {
}

class Treatment {
  + stage : int
}

class ConsentForm {
}

